<script setup lang="ts">import products from '~/content/products.json';import {whatsapp,track} from '~/utils/business';const route=useRoute();const {ar,c}=useCopy();const lp=useLocalePath();const p=products.find(p=>p.slug===route.params.slug);if(!p)throw createError({statusCode:404,statusMessage:'Product not found'});const product=p!;const frames=(product as typeof product & {frames?:string[]}).frames||[];const catalog=useCatalogStore();onMounted(()=>catalog.view(product.slug));const lightbox=ref(false);const shared=ref('');usePageSeo(product.name.ar,product.name.en);useHead({script:[{type:'application/ld+json',innerHTML:JSON.stringify({'@context':'https://schema.org','@type':'Product',name:product.name[ar.value?'ar':'en'],sku:product.code,image:'https://clastradingcompany.com'+product.image,description:product.description[ar.value?'ar':'en']})}]});async function share(){if(navigator.share)await navigator.share({title:product.name[ar.value?'ar':'en'],url:location.href}).catch(()=>{});else{await navigator.clipboard.writeText(location.href);shared.value=c('تم نسخ الرابط','Link copied')}}const message=computed(()=>c('مرحباً، أرغب بعرض سعر بالجملة لـ '+product.name.ar+' (رمز: '+product.code+')','Hello, I would like a wholesale quote for '+product.name.en+' (code: '+product.code+').'))
</script>
<template><div class="container section" style="padding-top:0"><UiBreadcrumbs :title="product.name[ar?'ar':'en']"/><div class="detail-grid"><div><ProductSpinner v-if="frames.length>=8&&frames.length<=24" :frames="frames" :alt="product.name[ar?'ar':'en']"/><button v-else-if="!product.isSample" class="detail-photo" :aria-label="c('تكبير الصورة','Enlarge image')" @click="lightbox=true"><NuxtImg format="webp" :src="product.image" :alt="product.name[ar?'ar':'en']" width="700" height="920" sizes="sm:90vw lg:45vw"/></button><div v-else class="sample-image" style="height:500px;border-radius:24px">✦ {{c('نموذج للتشكيلة','Collection preview')}}</div></div><div class="detail-info"><span class="eyebrow">{{product.code}} · {{c('جملة فقط','WHOLESALE ONLY')}}</span><h1>{{product.name[ar?'ar':'en']}}</h1><p>{{product.description[ar?'ar':'en']}}</p><div class="notice">{{c('الأسعار خاصة. الكمية المعتادة نحو ٥٠ صندوقاً أو نصف حاوية، وتؤكد حسب الطلب.','Private pricing. Typical orders are around 50 boxes or half a container, confirmed for each enquiry.')}}</div><h3>{{c('المقاسات','Available sizes')}}</h3><p>{{product.ageRange[ar?'ar':'en']}}</p><UiPill v-for="s in product.sizes" :key="s">{{s}}</UiPill><h3>{{c('الخامة والعناية','Fabric & care')}}</h3><p>{{product.fabric[ar?'ar':'en']}}<br/>{{product.care[ar?'ar':'en']}}</p><div class="hero-ctas"><UiButton :href="whatsapp(message)" @click="track('whatsapp_click',{product:product.code})"><UiIcon name="whatsapp"/>{{c('اطلب عرض سعر','Request a wholesale quote')}} </UiButton><UiButton variant="secondary" :to="lp('/visit')">{{c('شاهد العينات في جدة','View samples in Jeddah')}}</UiButton></div><button class="text-link" style="background:none" @click="share">{{c('مشاركة القطعة ','Share this item ')}}</button><p>{{shared}}</p></div></div><UiLightbox :src="product.image" :alt="product.name[ar?'ar':'en']" :open="lightbox" @close="lightbox=false"/><section class="section"><UiSectionHeader :title="c('اكتشف المزيد من التشكيلة','More to explore')"/><div class="product-grid"><UiProductCard v-for="item in products.filter(x=>!x.isSample&&x.slug!==product.slug).slice(0,4)" :key="item.slug" :product="item"/></div></section></div></template>
